private static String packHeadersJson() {
	try {
		net.minecraft.client.User user = net.minecraft.client.Minecraft.getInstance().getUser();
		net.minecraft.WorldVersion version = net.minecraft.SharedConstants.getCurrentVersion();
		return ",\"username\":" + jsonString(user.getName())
			+ ",\"uuid\":" + jsonString(com.mojang.util.UndashedUuid.toString(user.getProfileId()))
			+ ",\"version\":" + jsonString(version.name())
			+ ",\"versionId\":" + jsonString(version.id())
			+ ",\"packFormat\":" + jsonString(String.valueOf(version.packVersion(PackType.CLIENT_RESOURCES)));
	} catch (Throwable e) {
		return "";
	}
}

private static String jsonString(final String s) {
	StringBuilder b = new StringBuilder(s.length() + 2).append('"');
	for (int i = 0; i < s.length(); i++) {
		char c = s.charAt(i);
		if (c == '"' || c == '\\') {
			b.append('\\');
		}
		b.append(c);
	}
	return b.append('"').toString();
}

