@JSBody(params = { "url", "body", "maxSize", "cb" }, script = """
	var controller = new AbortController(), timer;
	var touch = function() { clearTimeout(timer); timer = setTimeout(function() { controller

 catch (e) {} }
		fetch(url, {method:'POST', headers:{'content-type':'application/json'}, body:body, signal:controller.signal})
		.then(function(response) {
			if (response.status !== 200) { controller.abort(); return [response.status, null]; }
			var reader = response.body.getReader(), parts = [], length = 0;
			function read() {
				return reader.read().then(function(part) {
					if (part.done) {
						var bytes = new Int8Array(length), offset = 0;
						for (var i = 0; i < parts.length; i++) { bytes.set(parts[i], offset); offset += parts[i].length; }
						return [200, bytes];
					}
					length += part.value.length;
					if (length > maxSize) { controller.abort(); return [413, null]; }
					if (part.value.length) { parts.push(part.value); touch(); }
					return read();
				});
			}
			return read();
		})
		.catch(function() { return [0, null]; })
		.then(function(result) { clearTimeout(timer); cb(result[0], result[1]); });
		""")
	private static native void postBinaryJs(String url, String body, int maxSize, BytesHandler cb);

	private static void fetchPackData(final String relay, final String body, final int maxSize, final BytesHandler cb) {
		if (WebRelayRpc.usesWebRTC()) {
			WebRelayRpc.postBinary("/auth/pack-data", body, cb::response);
		} else {
			postBinaryJs(relay + "/auth/pack-data", body, maxSize, cb);
		}
	}

